pragma solidity 0.8.36;
contract C { struct Payload { uint256 amount; bytes data; } function echoArray(uint256[] calldata values) external pure returns (uint256[] calldata) { return values; } function echoBytes(bytes calldata value) external pure returns (bytes calldata) { return value; } function echoStruct(Payload calldata value) external pure returns (Payload calldata) { return value; } function echoCallback(function(uint256) external returns (uint256) callback) external pure returns (function(uint256) external returns (uint256)) { return callback; } }
